import React from 'react'
import { z } from 'zod/v4'
import { FallbackToolUseErrorMessage } from '@thyrox/repl/components/FallbackToolUseErrorMessage.js'
import { FallbackToolUseRejectedMessage } from '@thyrox/repl/components/FallbackToolUseRejectedMessage.js'
import { MessageResponse } from '@thyrox/repl/components/MessageResponse.js'
import { Box, Text } from '@anthropic/ink'
import { useShortcutDisplay } from '@thyrox/repl/keybindings/useShortcutDisplay.js'
import type { TaskType } from '../../Task.js'
import type { Tool } from '../../Tool.js'
import { buildTool, type ToolDef } from '../../Tool.js'
import type { LocalAgentTaskState } from '@thyrox/agent/localAgentTask.js'
import type { LocalShellTaskState } from '@thyrox/repl/localShellTaskGuards.js'
import type { ShellCommandWithOutput } from '@thyrox/shell/shellCommand.js'
import type { RemoteAgentTaskState } from '../../tasks/RemoteAgentTask.js'
import type { TaskState } from '@thyrox/repl/tasksTypes.js'
import { AbortError } from '@thyrox/local-observability/errorHelpers.js'
import { lazySchema } from '../../utils/lazySchema.js'
import { extractTextContent } from '@thyrox/agent/messages.js'
import { semanticBoolean } from '../../utils/semanticBoolean.js'
import { sleep } from '@thyrox/config/sleep'
import { jsonParse } from '@thyrox/local-observability/slowOperations.js'
import { countCharInString } from '@thyrox/output/utils/stringUtils.js'
import { getTaskOutput } from '@thyrox/storage/task/diskOutput.js'
import { updateTaskState } from '@thyrox/agent/taskFramework.js'
import { formatTaskOutput } from '../../task/outputFormatting.js'
import type { ThemeName } from '@anthropic/ink'
import { AgentPromptDisplay, AgentResponseDisplay } from '../AgentTool/UI.js'
import BashToolResultMessage from '../BashTool/BashToolResultMessage.js'
import { TASK_OUTPUT_TOOL_NAME } from './constants.js'

const inputSchema = lazySchema(() =>
  z.strictObject({
    task_id: z.string().describe('The task ID to get output from'),
    block: semanticBoolean(z.boolean().default(true)).describe(
      'Whether to wait for completion',
    ),
    timeout: z
      .number()
      .min(0)
      .max(600000)
      .default(30000)
      .describe('Max wait time in ms'),
  }),
)
type InputSchema = ReturnType<typeof inputSchema>

type TaskOutputToolInput = z.infer<InputSchema>

// Unified output type covering all task types
type TaskOutput = {
  task_id: string
  task_type: TaskType
  status: string
  description: string
  output: string
  exitCode?: number | null
  error?: string
  // For agents
  prompt?: string
  result?: string
}

type TaskOutputToolOutput = {
  retrieval_status: 'success' | 'timeout' | 'not_ready'
  task: TaskOutput | null
}

// Re-export Progress from centralized types to break import cycles
export type { TaskOutputProgress as Progress } from '../../progressTypes.js'

// Get output for any task type
async function getTaskOutputData(task: TaskState): Promise<TaskOutput> {
  let output: string
  if (task.type === 'local_bash') {
    const bashTask = task as LocalShellTaskState
    // shellCommand siempre lo puebla exec(), que devuelve ShellCommandWithOutput;
    // el campo del estado sólo declara el contrato base ShellCommand.
    const shellCommand = bashTask.shellCommand as ShellCommandWithOutput | null
    const taskOutputObj = shellCommand?.taskOutput
    if (taskOutputObj) {
      const stdout = await taskOutputObj.getStdout()
      const stderr = taskOutputObj.getStderr()
      output = [stdout, stderr].filter(Boolean).join('\n')
    } else {
      output = await getTaskOutput(task.id)
    }
  } else {
    output = await getTaskOutput(task.id)
  }

  const baseOutput: TaskOutput = {
    task_id: task.id,
    task_type: task.type,
    status: task.status,
    description: task.description,
    output,
  }

  // Add type-specific fields
  if (task.type === 'local_bash') {
    const bashTask = task as LocalShellTaskState
    return {
      ...baseOutput,
      exitCode: bashTask.result?.code ?? null,
    }
  }

  if (task.type === 'local_agent') {
    const agentTask = task as LocalAgentTaskState
    // Prefer the clean final answer from the in-memory result over the raw
    // JSONL transcript on disk. The disk output is a symlink to the full
    // session transcript (every message, tool use, etc.), not just the
    // subagent's answer. The in-memory result contains only the final
    // assistant text content blocks.
    const cleanResult = agentTask.result
      ? extractTextContent(agentTask.result.content, '\n')
      : undefined
    return {
      ...baseOutput,
      prompt: agentTask.prompt,
      result: cleanResult || output,
      output: cleanResult || output,
      error: agentTask.error,
    }
  }

  if (task.type === 'remote_agent') {
    const remoteTask = task as RemoteAgentTaskState
    return {
      ...baseOutput,
      prompt: remoteTask.command,
    }
  }

  return baseOutput
}

// Wait for task to complete
async function waitForTaskCompletion(
  taskId: string,
  getAppState: () => { tasks?: Record<string, TaskState> },
  timeoutMs: number,
  abortController?: AbortController,
): Promise<TaskState | null> {
  const startTime = Date.now()

  while (Date.now() - startTime < timeoutMs) {
    // Check abort signal
    if (abortController?.signal.aborted) {
      throw new AbortError()
    }

    const state = getAppState()
    const task = state.tasks?.[taskId] as TaskState | undefined

    if (!task) {
      return null
    }

    if (task.status !== 'running' && task.status !== 'pending') {
      return task
    }

    // Wait before polling again
    await sleep(100)
  }

  // Timeout - return current state
  const finalState = getAppState()
  return (finalState.tasks?.[taskId] as TaskState) ?? null
}

export const TaskOutputTool: Tool<InputSchema, TaskOutputToolOutput> =
  buildTool({
    name: TASK_OUTPUT_TOOL_NAME,
    searchHint: 'read output/logs from a background task',
    maxResultSizeChars: 100_000,
    shouldDefer: true,
    // Backwards-compatible aliases for renamed tools
    aliases: ['AgentOutputTool', 'BashOutputTool'],

    userFacingName() {
      return 'Task Output'
    },

    get inputSchema(): InputSchema {
      return inputSchema()
    },

    async description() {
      return '[Deprecated] — prefer Read on the task output file path'
    },

    isConcurrencySafe(_input) {
      return this.isReadOnly?.(_input) ?? false
    },

    isEnabled() {
      return process.env.USER_TYPE !== 'ant'
    },

    isReadOnly(_input) {
      return true
    },
    toAutoClassifierInput(input) {
      return input.task_id
    },

    async prompt() {
      return `DEPRECATED: Prefer using the Read tool on the task's output file path instead. Background tasks return their output file path in the tool result, and you receive a <task-notification> with the same path when the task completes — Read that file directly.

- Retrieves output from a running or completed task (background shell, agent, or remote session)
- Takes a task_id parameter identifying the task
- Returns the task output along with status information
- Use block=true (default) to wait for task completion
- Use block=false for non-blocking check of current status
- Task IDs can be found using the /tasks command
- Works with all task types: background shells, async agents, and remote sessions`
    },

    async validateInput({ task_id }, { getAppState }) {
      if (!task_id) {
        return {
          result: false,
          message: 'Task ID is required',
          errorCode: 1,
        }
      }

      const appState = getAppState()
      const task = appState.tasks?.[task_id] as TaskState | undefined

      if (!task) {
        return {
          result: false,
          message: `No task found with ID: ${task_id}`,
          errorCode: 2,
        }
      }

      return { result: true }
    },

    async call(
      input: TaskOutputToolInput,
      toolUseContext,
      _canUseTool,
      _parentMessage,
      onProgress,
    ) {
      const { task_id, block, timeout } = input

      const appState = toolUseContext.getAppState()
      const task = appState.tasks?.[task_id] as TaskState | undefined

      if (!task) {
        throw new Error(`No task found with ID: ${task_id}`)
      }

      if (!block) {
        // Non-blocking: return current state
        if (task.status !== 'running' && task.status !== 'pending') {
          // Mark as notified
          updateTaskState(task_id, toolUseContext.setAppState, t => ({
            ...t,
            notified: true,
          }))
          return {
            data: {
              retrieval_status: 'success' as const,
              task: await getTaskOutputData(task),
            },
          }
        }
        return {
          data: {
            retrieval_status: 'not_ready' as const,
            task: await getTaskOutputData(task),
          },
        }
      }

      // Blocking: wait for completion
      if (onProgress) {
        onProgress({
          toolUseID: `task-output-waiting-${Date.now()}`,
          data: {
            type: 'waiting_for_task',
            taskDescription: task.description,
            taskType: task.type,
          },
        })
      }

      const completedTask = await waitForTaskCompletion(
        task_id,
        toolUseContext.getAppState,
        timeout,
        toolUseContext.abortController,
      )

      if (!completedTask) {
        return {
          data: {
            retrieval_status: 'timeout' as const,
            task: null,
          },
        }
      }

      if (
        completedTask.status === 'running' ||
        completedTask.status === 'pending'
      ) {
        return {
          data: {
            retrieval_status: 'timeout' as const,
            task: await getTaskOutputData(completedTask),
          },
        }
      }

      // Mark as notified
      updateTaskState(task_id, toolUseContext.setAppState, t => ({
        ...t,
        notified: true,
      }))

      return {
        data: {
          retrieval_status: 'success' as const,
          task: await getTaskOutputData(completedTask),
        },
      }
    },

    mapToolResultToToolResultBlockParam(data, toolUseID) {
      const parts: string[] = []

      parts.push(
        `<retrieval_status>${data.retrieval_status}</retrieval_status>`,
      )

      if (data.task) {
        parts.push(`<task_id>${data.task.task_id}</task_id>`)
        parts.push(`<task_type>${data.task.task_type}</task_type>`)
        parts.push(`<status>${data.task.status}</status>`)

        if (data.task.exitCode !== undefined && data.task.exitCode !== null) {
          parts.push(`<exit_code>${data.task.exitCode}</exit_code>`)
        }

        if (data.task.output?.trim()) {
          const { content } = formatTaskOutput(
            data.task.output,
            data.task.task_id,
          )
          parts.push(`<output>\n${content.trimEnd()}\n</output>`)
        }

        if (data.task.error) {
          parts.push(`<error>${data.task.error}</error>`)
        }
      }

      return {
        tool_use_id: toolUseID,
        type: 'tool_result' as const,
        content: parts.join('\n\n'),
      }
    },

    renderToolUseMessage(input) {
      const { block = true } = input
      if (!block) {
        return 'non-blocking'
      }
      return ''
    },

    renderToolUseTag(input) {
      if (!input.task_id) {
        return null
      }
      return <Text dimColor> {input.task_id}</Text>
    },

    renderToolUseProgressMessage(progressMessages) {
      const lastProgress = progressMessages[progressMessages.length - 1]
      const progressData = lastProgress?.data as
        | { taskDescription?: string; taskType?: string }
        | undefined

      return (
        <Box flexDirection="column">
          {progressData?.taskDescription && (
            <Text>&nbsp;&nbsp;{progressData.taskDescription}</Text>
          )}
          <Text>
            &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Waiting for task{' '}
            <Text dimColor>(esc to give additional instructions)</Text>
          </Text>
        </Box>
      )
    },

    renderToolResultMessage(content, _, { verbose, theme }) {
      return (
        <TaskOutputResultDisplay
          content={content}
          verbose={verbose}
          theme={theme}
        />
      )
    },

    renderToolUseRejectedMessage() {
      return <FallbackToolUseRejectedMessage />
    },

    renderToolUseErrorMessage(result, { verbose }) {
      return <FallbackToolUseErrorMessage result={result} verbose={verbose} />
    },
  } satisfies ToolDef<InputSchema, TaskOutputToolOutput>)

function TaskOutputResultDisplay({
  content,
  verbose = false,
  theme,
}: {
  content: string | TaskOutputToolOutput
  verbose?: boolean
  theme: ThemeName
}): React.ReactNode {
  const expandShortcut = useShortcutDisplay(
    'app:toggleTranscript',
    'Global',
    'ctrl+o',
  )
  const result: TaskOutputToolOutput =
    typeof content === 'string' ? jsonParse(content) : content

  if (!result.task) {
    return (
      <MessageResponse>
        <Text dimColor>No task output available</Text>
      </MessageResponse>
    )
  }

  const { task } = result

  // For shell tasks, render like BashToolResultMessage
  if (task.task_type === 'local_bash') {
    const bashOut = {
      stdout: task.output,
      stderr: '',
      isImage: false,
      dangerouslyDisableSandbox: true,
      returnCodeInterpretation: task.error,
    }
    return <BashToolResultMessage content={bashOut} verbose={verbose} />
  }

  // For agent tasks, render with prompt/response display
  if (task.task_type === 'local_agent') {
    const lineCount = task.result ? countCharInString(task.result, '\n') + 1 : 0

    if (result.retrieval_status === 'success') {
      if (verbose) {
        return (
          <Box flexDirection="column">
            <Text>
              {task.description} ({lineCount} lines)
            </Text>
            <Box flexDirection="column" paddingLeft={2} marginTop={1}>
              {task.prompt && (
                <AgentPromptDisplay prompt={task.prompt} theme={theme} dim />
              )}
              {task.result && (
                <Box marginTop={1}>
                  <AgentResponseDisplay
                    content={[{ type: 'text', text: task.result }]}
                    theme={theme}
                  />
                </Box>
              )}
              {task.error && (
                <Box flexDirection="column" marginTop={1}>
                  <Text color="error" bold>
                    Error:
                  </Text>
                  <Box paddingLeft={2}>
                    <Text color="error">{task.error}</Text>
                  </Box>
                </Box>
              )}
            </Box>
          </Box>
        )
      }
      return (
        <MessageResponse>
          <Text dimColor>Read output ({expandShortcut} to expand)</Text>
        </MessageResponse>
      )
    }

    if (result.retrieval_status === 'timeout' || task.status === 'running') {
      return (
        <MessageResponse>
          <Text dimColor>Task is still running…</Text>
        </MessageResponse>
      )
    }

    if (result.retrieval_status === 'not_ready') {
      return (
        <MessageResponse>
          <Text dimColor>Task is still running…</Text>
        </MessageResponse>
      )
    }

    return (
      <MessageResponse>
        <Text dimColor>Task not ready</Text>
      </MessageResponse>
    )
  }

  // For remote agent tasks
  if (task.task_type === 'remote_agent') {
    return (
      <Box flexDirection="column">
        <Text>
          &nbsp;&nbsp;{task.description} [{task.status}]
        </Text>
        {task.output && verbose && (
          <Box paddingLeft={4} marginTop={1}>
            <Text>{task.output}</Text>
          </Box>
        )}
        {!verbose && task.output && (
          <Text dimColor>
            {'     '}({expandShortcut} to expand)
          </Text>
        )}
      </Box>
    )
  }

  // Default rendering
  return (
    <Box flexDirection="column">
      <Text>
        &nbsp;&nbsp;{task.description} [{task.status}]
      </Text>
      {task.output && (
        <Box paddingLeft={4}>
          <Text>{task.output.slice(0, 500)}</Text>
        </Box>
      )}
    </Box>
  )
}

/**
 * La mitad ROJA de TodoWrite y de las tres piezas que lo bloqueaban.
 *
 * Procedencia: `ccnmt: packages/tool-registry/src/{todo/types.ts,
 * tools/AgentTool/constants.ts, tools/FileEditTool/constants.ts,
 * tools/TodoWriteTool/}`. Ese árbol no declara licencia, así que los cuerpos
 * se reimplementan y no se copian.
 *
 * POR QUÉ ESTE TRAMO Y NO TaskCreate. El sondeo anterior midió que los
 * ESPECIFICADORES de TaskCreateTool resuelven, y concluyó que estaba libre.
 * Medido ahora a nivel de SÍMBOLO, no lo está: importa
 * `executeTaskCreatedHooks` de `@thyrox/agent/hooks.js`, y ese archivo aquí
 * exporta 7 símbolos, ninguno de ellos ése — es el motor de hooks
 * (`executeHooks`, 5427 líneas en la fuente), que no está portado. Medir el
 * significante (¿resuelve el módulo?) y concluir sobre el significado
 * (¿existe el símbolo?) es el sub-patrón C, y produjo un falso «libre».
 *
 * TodoWrite sí lo está: sus tres importaciones de paquete hermano
 * —`getSessionId`, `getFeatureValue_CACHED_MAY_BE_STALE`, `isTodoV2Enabled`—
 * se comprobaron por carga real, y sus tres bloqueos son locales y baratos.
 *
 * Métrica: qué guarda TodoWrite en el estado, cuándo se habilita, y qué
 * texto arma para quien lee el resultado.
 * Ciega a: el despacho —si el bucle lo llama— y la rama del empujón de
 * verificación, que exige la macro `feature('VERIFICATION_AGENT')` y aquí es
 * un sustituto que siempre devuelve `false` (ver `pendingCrossPackageDeps`).
 */
import { afterEach, beforeEach, describe, expect, test } from 'bun:test'
import {
  resetStateForTests,
  setIsInteractive,
} from '@thyrox/app-host/bootstrap/state.js'
import {
  AGENT_TOOL_NAME,
  LEGACY_AGENT_TOOL_NAME,
  ONE_SHOT_BUILTIN_AGENT_TYPES,
  VERIFICATION_AGENT_TYPE,
} from '../AgentTool/constants.ts'
import {
  CLAUDE_FOLDER_PERMISSION_PATTERN,
  FILE_EDIT_TOOL_NAME,
  FILE_UNEXPECTEDLY_MODIFIED_ERROR,
  GLOBAL_CLAUDE_FOLDER_PERMISSION_PATTERN,
} from '../FileEditTool/constants.ts'
import { TodoItemSchema, TodoListSchema, type TodoList } from '../../todo/types.ts'
import { TodoWriteTool } from '../TodoWriteTool/TodoWriteTool.ts'

let estado: Record<string, any>

/** El contexto que `call` recibe: sólo lee y escribe el estado. */
function ctx(agentId?: string) {
  return {
    agentId,
    getAppState: () => estado,
    setAppState: (f: (prev: any) => any) => {
      estado = f(estado)
    },
  } as never
}

beforeEach(() => {
  estado = { todos: {} }
  resetStateForTests()
  setIsInteractive(true)
})

afterEach(() => {
  resetStateForTests()
})

describe('AgentTool/constants — 3 casos', () => {
  test('1. el nombre de protocolo y su forma heredada son distintos', () => {
    // El heredado NO se retira: lo siguen citando reglas de permiso, hooks y
    // sesiones reanudadas escritas antes del renombre.
    expect(AGENT_TOOL_NAME).toBe('Agent')
    expect(LEGACY_AGENT_TOOL_NAME).toBe('Task')
  })

  test('2. el tipo de agente verificador se nombra en minúscula', () => {
    expect(VERIFICATION_AGENT_TYPE).toBe('verification')
  })

  test('3. los agentes de un solo tiro son un conjunto, no una lista', () => {
    // Es un `Set` porque el consumidor pregunta por pertenencia en cada
    // vuelta; con un arreglo el coste sería lineal y `.has` no existiría.
    expect(ONE_SHOT_BUILTIN_AGENT_TYPES.has('Explore')).toBe(true)
    expect(ONE_SHOT_BUILTIN_AGENT_TYPES.has('Plan')).toBe(true)
    expect(ONE_SHOT_BUILTIN_AGENT_TYPES.has('Agent')).toBe(false)
    expect(ONE_SHOT_BUILTIN_AGENT_TYPES.size).toBe(2)
  })
})

describe('FileEditTool/constants — 2 casos', () => {
  test('4. las cuatro constantes llevan su valor de la fuente', () => {
    expect(FILE_EDIT_TOOL_NAME).toBe('Edit')
    expect(CLAUDE_FOLDER_PERMISSION_PATTERN).toBe('/.claude/**')
    expect(GLOBAL_CLAUDE_FOLDER_PERMISSION_PATTERN).toBe('~/.claude/**')
    expect(FILE_UNEXPECTEDLY_MODIFIED_ERROR).toContain(
      'unexpectedly modified',
    )
  })

  test('5. el archivo NO importa nada — es su razón de existir', async () => {
    // La fuente lo declara en su primera línea: «In its own file to avoid
    // circular dependencies». Un import aquí reintroduce el ciclo que el
    // archivo existe para cortar.
    const texto = await Bun.file(
      new URL('../FileEditTool/constants.ts', import.meta.url),
    ).text()
    expect(texto).not.toMatch(/^\s*import\s/m)
  })
})

describe('todo/types — 4 casos', () => {
  test('6. un item válido pasa con sus tres campos', () => {
    const r = TodoItemSchema().safeParse({
      content: 'correr las pruebas',
      status: 'in_progress',
      activeForm: 'corriendo las pruebas',
    })
    expect(r.success).toBe(true)
  })

  test('7. el contenido vacío se rechaza, y el mensaje lo dice', () => {
    const r = TodoItemSchema().safeParse({
      content: '',
      status: 'pending',
      activeForm: 'algo',
    })
    expect(r.success).toBe(false)
    expect(JSON.stringify(r.error)).toContain('Content cannot be empty')
  })

  test('8. la forma activa vacía se rechaza aparte del contenido', () => {
    const r = TodoItemSchema().safeParse({
      content: 'algo',
      status: 'pending',
      activeForm: '',
    })
    expect(r.success).toBe(false)
    expect(JSON.stringify(r.error)).toContain('Active form cannot be empty')
  })

  test('9. el estado es un enum cerrado de tres', () => {
    for (const status of ['pending', 'in_progress', 'completed']) {
      expect(
        TodoItemSchema().safeParse({ content: 'c', status, activeForm: 'a' })
          .success,
      ).toBe(true)
    }
    expect(
      TodoItemSchema().safeParse({
        content: 'c',
        status: 'blocked',
        activeForm: 'a',
      }).success,
    ).toBe(false)
    expect(TodoListSchema().safeParse([]).success).toBe(true)
  })
})

describe('TodoWriteTool — 8 casos', () => {
  test('10. se nombra TodoWrite y NO se muestra a la persona', () => {
    // La cadena vacía es deliberada en la fuente: el útil no aparece en la
    // línea de estado, sólo su efecto en el panel.
    expect(TodoWriteTool.name).toBe('TodoWrite')
    expect(TodoWriteTool.userFacingName()).toBe('')
  })

  test('11. se habilita al REVÉS que la familia Task', () => {
    // Es la decisión que hace que las dos familias no coexistan: TaskGet y
    // TaskList se encienden con `isTodoV2Enabled()`, éste con su negación.
    setIsInteractive(true)
    expect(TodoWriteTool.isEnabled()).toBe(false)
    setIsInteractive(false)
    expect(TodoWriteTool.isEnabled()).toBe(true)
  })

  test('12. no pide permiso: devuelve la entrada intacta', async () => {
    const entrada = { todos: [] }
    const r = await TodoWriteTool.checkPermissions(entrada as never)
    expect(r).toEqual({ behavior: 'allow', updatedInput: entrada })
  })

  test('13. la lista se guarda bajo el id de sesión cuando no hay agente', async () => {
    const todos = [
      { content: 'una', status: 'pending', activeForm: 'haciendo una' },
    ]
    await TodoWriteTool.call({ todos } as never, ctx())
    const claves = Object.keys(estado.todos)
    expect(claves).toHaveLength(1)
    expect(estado.todos[claves[0]!]).toEqual(todos)
  })

  test('14. un subagente escribe bajo SU id, no bajo el de la sesión', async () => {
    // Sin esta separación, dos subagentes concurrentes se pisarían la lista.
    const todos = [
      { content: 'una', status: 'pending', activeForm: 'haciendo una' },
    ]
    await TodoWriteTool.call({ todos } as never, ctx('agente-7'))
    expect(estado.todos['agente-7']).toEqual(todos)
  })

  test('15. una lista TODA completada se VACÍA en el estado', async () => {
    // Es la decisión no obvia: el panel no debe quedar con una lista de
    // tareas hechas, porque la siguiente vuelta la leería como trabajo vivo.
    const todos = [
      { content: 'una', status: 'completed', activeForm: 'haciendo una' },
      { content: 'dos', status: 'completed', activeForm: 'haciendo dos' },
    ]
    await TodoWriteTool.call({ todos } as never, ctx())
    const clave = Object.keys(estado.todos)[0]!
    expect(estado.todos[clave]).toEqual([])
  })

  test('16. pero el resultado devuelve la lista COMPLETA, no la vaciada', async () => {
